const data = $input.item.json.data ?? '';
const statusCode = $input.item.json.statusCode ?? 0;

const indicators = [
  { re: /PerimeterX|_pxParam|px-captcha|pxCaptcha|_px\b/, name: 'PerimeterX' },
  { re: /cf_chl_|cf-browser-verification|__cf_chl_|Just a moment\.\.\.|Enable JavaScript and cookies to continue/, name: 'Cloudflare Challenge' },
  { re: /DataDome|datadome\.co/, name: 'DataDome' },
  { re: /incapsula|visid_incap|reese84/, name: 'Imperva/Incapsula' },
  { re: /AkamaiGHost|akamai_bot/, name: 'Akamai Bot Manager' },
  { re: /human\.security|shape\.service|f5bot/, name: 'F5/Shape Security' },
  { re: /verifyHuman|Are you a human|robot check|robotcheck|Pardon Our Interruption/, name: 'Generic Bot Check' }
];

let blockType = null;
for (const ind of indicators) {
  if (ind.re.test(data)) { blockType = ind.name; break; }
}

const isRealHtml = /<html|<body|<!DOCTYPE/i.test(data);
const isJsonBlob = /^\s*[\{\[]/.test(data) && !data.includes('<');
const isTiny = data.trim().length < 800 && !isRealHtml;
const isBlocked = !!blockType || isJsonBlob || isTiny;
const effectiveBlockType = blockType || (isBlocked ? 'Página bloqueada ou resposta inválida' : null);

return [{ json: {
  ...($input.item.json),
  is_bot_blocked: isBlocked,
  block_type: effectiveBlockType,
  html_length: data.length,
  is_real_html: isRealHtml
}}];

const item = $input.first().json;

// Check for OpenRouter API error (e.g. 401 unauthorized, 429 rate limit)
if (item.error || (item.choices === undefined && item.message)) {
  const getUrl = () => { try { return $('Prepare Context').item.json.url; } catch(e){ return ''; } };
  const errMsg = item.error?.message ?? item.message ?? JSON.stringify(item);
  return [{ json: { error: true, message: 'Erro OpenRouter: ' + errMsg, url: getUrl() } }];
}

// Extract text from OpenRouter chat completions response
const raw = (item.choices?.[0]?.message?.content ?? item.output ?? '').trim();
const getUrl = () => { try { return $('Prepare Context').item.json.url; } catch(e){ return ''; } };

if (!raw) {
  return [{ json: { error: true, message: 'Resposta vazia do modelo. Verifique as credenciais OpenRouter.', url: getUrl() } }];
}

try {
  const blockMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  const cleaned = blockMatch ? blockMatch[1].trim() : raw;
  const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
  if (s < 0 || e <= s) throw new Error('JSON nao encontrado na resposta.');
  const d = JSON.parse(cleaned.slice(s, e + 1));
  return [{ json: { ...d, url: getUrl() } }];
} catch(err) {
  return [{ json: { error: true, message: 'Falha ao parsear resposta: ' + err.message, raw_preview: raw.substring(0, 300), url: getUrl() } }];
}

const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const url = (body.url ?? '').trim();
const context = (body.context ?? '').trim() || 'Nao informado';
if (!url) throw new Error('URL obrigatoria.');
return [{ json: { url, context } }];

const ctx = $input.first().json;

const userMsg = [
  'URL: ' + ctx.url,
  'Contexto: ' + (ctx.context || 'Não informado'),
  'Anti-bot bloqueado: ' + ctx.is_bot_blocked + ' | Tipo: ' + (ctx.block_type || 'none'),
  'llms_txt_status: ' + ctx.llms_txt_status,
  'llms_txt_content (primeiros 500 chars):\n' + (ctx.llms_txt_content || '').substring(0, 300),
  'HTML da página (primeiros 3000 chars):\n' + (ctx.page_html || '').substring(0, 3000)
].join('\n');

return [{json: {
  model: 'anthropic/claude-sonnet-4.6',
  messages: [
    {role: 'system', content: "Voc\u00ea \u00e9 auditor de Agentic Browsing (Lighthouse v13.3+) e especialista GEO.\nAnalise os dados e retorne SOMENTE JSON puro, sem markdown, sem texto extra.\n\nScore: fra\u00e7\u00e3o X/Y onde Y = audits aplic\u00e1veis (N/A exclui do denominador). M\u00e1x 5/5.\n\nAUDITS:\n1. llms-txt [1pt]: PASS se present+H1(regex /^\\s*#\\s+\\S/m)+link([...](...))+ \u226550chars. FAIL se 2xx sem crit\u00e9rios ou 5xx. N/A se not_found/4xx.\n2. accessibility-tree [1pt total]: PASS somente se TODOS os 12 sub-audits passam. FAIL se qualquer falha. INDETERMINATE se is_bot_blocked=true (n\u00e3o conta no score).\n   12 sub-audits: button-name[critical], link-name[serious], label[critical], image-alt[critical], aria-required-attr[critical], aria-valid-attr[critical], aria-roles[critical], aria-hidden-focus[serious], aria-command-name[serious], aria-meter-name[serious], aria-progressbar-name[serious], aria-tooltip-body-and-role[moderate]\n3. webmcp-registered-tools [informative]: conta tools MCP; INFORMATIVE, n\u00e3o entra no score.\n4. webmcp-form-coverage [1pt]: forms t\u00eam anota\u00e7\u00e3o MCP? PASS/FAIL/N/A (N/A se sem forms).\n5. webmcp-schema-validity [1pt]: JSON-Schema v\u00e1lido? PASS/FAIL/N/A (N/A se sem schema).\n6. cumulative-layout-shift [1pt]: risco CLS vis\u00edvel no HTML? PASS(baixo risco)/FAIL(alto risco).\n\nRetorne este JSON exato (preencha os valores):\n{\"passed_count\":0,\"total_count\":0,\"infrastructure_issues\":[],\"geo_readiness\":{\"level\":\"poor\",\"main_barrier\":\"\",\"ai_access_score\":\"0/0\"},\"llms_txt\":{\"status\":\"not_applicable\",\"present\":false,\"has_h1\":false,\"has_links\":false,\"length_ok\":false,\"finding\":\"\",\"recommendation\":\"\"},\"webmcp\":{\"registered_tools\":{\"status\":\"informative\",\"count\":0,\"finding\":\"\"},\"form_coverage\":{\"status\":\"not_applicable\",\"finding\":\"\",\"recommendation\":\"\"},\"schema_validity\":{\"status\":\"not_applicable\",\"finding\":\"\",\"recommendation\":\"\"}},\"accessibility_tree\":{\"status\":\"fail\",\"is_well_formed\":false,\"passed\":0,\"total\":12,\"audits\":[{\"id\":\"button-name\",\"status\":\"fail\",\"impact\":\"critical\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"link-name\",\"status\":\"fail\",\"impact\":\"serious\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"label\",\"status\":\"fail\",\"impact\":\"critical\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"image-alt\",\"status\":\"fail\",\"impact\":\"critical\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-required-attr\",\"status\":\"fail\",\"impact\":\"critical\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-valid-attr\",\"status\":\"fail\",\"impact\":\"critical\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-roles\",\"status\":\"fail\",\"impact\":\"critical\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-hidden-focus\",\"status\":\"fail\",\"impact\":\"serious\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-command-name\",\"status\":\"fail\",\"impact\":\"serious\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-meter-name\",\"status\":\"fail\",\"impact\":\"serious\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-progressbar-name\",\"status\":\"fail\",\"impact\":\"serious\",\"finding\":\"\",\"recommendation\":\"\"},{\"id\":\"aria-tooltip-body-and-role\",\"status\":\"fail\",\"impact\":\"moderate\",\"finding\":\"\",\"recommendation\":\"\"}]},\"cumulative_layout_shift\":{\"status\":\"pass\",\"risk_level\":\"low\",\"factors\":[],\"recommendation\":\"\"},\"top_quick_wins\":[{\"priority\":1,\"action\":\"\",\"effort\":\"low\",\"geo_context\":\"\"},{\"priority\":2,\"action\":\"\",\"effort\":\"low\",\"geo_context\":\"\"},{\"priority\":3,\"action\":\"\",\"effort\":\"medium\",\"geo_context\":\"\"}],\"summary\":\"\"}"},
    {role: 'user', content: userMsg}
  ],
  max_tokens: 1000,
  temperature: 0.1
}}];
